/* Generated by Trae Work — AI 会话架构 Diff 报告交互脚本
 * 职责：Mermaid 图表渲染（3 张）、ECharts 数据图渲染（2 张）、目录滚动高亮
 * 配色与文档 CSS 变量严格对齐：暖橙 accent / 青 accent2 / 暖纸 bg
 */
(function () {
  'use strict';

  var FONT = "'Outfit','PingFang SC','Noto Sans CJK SC','Microsoft YaHei',sans-serif";
  var MONO = "'JetBrains Mono',Menlo,Consolas,monospace";
  var C = {
    ink: '#1c1f26',
    muted: '#6b7280',
    rule: '#e2ddd2',
    bg: '#f7f5f0',
    bg2: '#ffffff',
    bg3: '#efece4',
    accent: '#c2410c',
    accentSoft: '#fdf0e8',
    accent2: '#0f766e',
    accent2Soft: '#e6f4f2',
    warn: '#b45309'
  };

  /* ================================================================
   * 1. Mermaid：流程图 ×2 + 甘特图 ×1
   * ================================================================ */
  if (window.mermaid) {
    try {
      mermaid.initialize({
        startOnLoad: false,
        securityLevel: 'loose',
        theme: 'base',
        fontFamily: FONT,
        themeVariables: {
          background: C.bg2,
          primaryColor: C.accentSoft,
          primaryBorderColor: C.accent,
          primaryTextColor: C.ink,
          lineColor: C.muted,
          secondaryColor: C.accent2Soft,
          secondaryBorderColor: C.accent2,
          secondaryTextColor: C.ink,
          tertiaryColor: C.bg3,
          tertiaryBorderColor: C.muted,
          tertiaryTextColor: C.ink,
          fontFamily: FONT,
          fontSize: '14px',
          /* flowchart */
          nodeBorder: C.accent,
          clusterBkg: '#ffffff',
          clusterBorder: C.rule,
          edgeLabelBackground: '#ffffff',
          /* gantt */
          sectionBkgColor: C.accent2Soft,
          altSectionBkgColor: '#ffffff',
          gridColor: C.rule,
          weekendBkgColor: C.bg3,
          taskBkgColor: C.accent2,
          taskBorderColor: C.accent2,
          taskTextColor: '#ffffff',
          taskTextLightColor: '#ffffff',
          taskTextDarkColor: C.ink,
          taskTextClickableColor: C.accent,
          activeTaskBkgColor: C.accent,
          activeTaskBorderColor: C.accent,
          doneTaskBkgColor: C.muted,
          doneTaskBorderColor: C.muted,
          critBkgColor: C.warn,
          critBorderColor: C.warn,
          todayLineColor: C.accent
        },
        flowchart: {
          htmlLabels: true,
          curve: 'basis',
          padding: 14,
          nodeSpacing: 42,
          rankSpacing: 48,
          useMaxWidth: true
        },
        gantt: {
          fontSize: 12,
          sectionFontSize: 12,
          numberSectionStyles: 4,
          barHeight: 20,
          barGap: 7,
          topPadding: 34,
          leftPadding: 168,
          gridLineStartPadding: 38
        }
      });
    } catch (e) {
      console.warn('mermaid initialize failed:', e);
    }

    var diagrams = Array.prototype.slice.call(document.querySelectorAll('pre.mermaid'));
    diagrams.forEach(function (el, i) {
      var code = el.textContent;
      var renderId = 'mmd-' + i + '-' + Date.now();
      try {
        mermaid.render(renderId, code).then(function (r) {
          el.innerHTML = r.svg;
          el.classList.add('rendered');
          if (typeof r.bindFunctions === 'function') {
            try { r.bindFunctions(el); } catch (_) {}
          }
        }).catch(function (err) {
          showMermaidFallback(el, code, err);
        });
      } catch (err) {
        showMermaidFallback(el, code, err);
      }
    });
  }

  function showMermaidFallback(el, code, err) {
    var box = document.createElement('div');
    box.style.cssText = 'border:1px dashed ' + C.rule + ';border-radius:10px;padding:16px;background:' + C.bg2 + ';';
    var p = document.createElement('p');
    p.style.cssText = 'margin:0 0 10px;color:' + C.warn + ';font-size:13px;font-family:' + FONT + ';';
    p.textContent = '图表渲染失败，以下为 Mermaid 源码：';
    var pre = document.createElement('pre');
    pre.style.cssText = 'margin:0;white-space:pre-wrap;font-family:' + MONO + ';font-size:12px;line-height:1.6;color:' + C.ink + ';';
    pre.textContent = code;
    box.appendChild(p);
    box.appendChild(pre);
    if (el.parentNode) { el.parentNode.replaceChild(box, el); }
    console.warn('mermaid render error:', err);
  }

  /* ================================================================
   * 2. ECharts
   * ================================================================ */
  var charts = [];

  function baseOption() {
    return {
      textStyle: { fontFamily: FONT, color: C.ink },
      tooltip: {
        trigger: 'axis',
        backgroundColor: C.bg2,
        borderColor: C.rule,
        borderWidth: 1,
        textStyle: { color: C.ink, fontFamily: FONT, fontSize: 13 },
        extraCssText: 'box-shadow:0 6px 20px rgba(28,31,38,0.10);border-radius:8px;'
      },
      grid: { left: 8, right: 24, top: 42, bottom: 8, containLabel: true }
    };
  }

  function initChart(id, option) {
    var dom = document.getElementById(id);
    if (!dom || !window.echarts) {
      if (dom) dom.innerHTML = '<div style="padding:24px;color:' + C.muted + ';font-size:13px;text-align:center;">图表库未加载，请在联网环境下打开本报告。</div>';
      return null;
    }
    var chart = echarts.init(dom, null, { renderer: 'canvas' });
    chart.setOption(option);
    charts.push(chart);
    return chart;
  }

  /* ---------- 图 1：采用与信任的剪刀差 ---------- */
  (function () {
    var cats = [
      '每日使用 AI 编程工具',
      '正在使用 AI 编程工具',
      '生产新代码中 AI 生成占比',
      '调试 AI 代码比手写更耗时',
      '信任随 AI 工具交付的代码'
    ];
    var adopt = [92, 84, 41, null, null];   // 采用侧（橙）
    var trust = [null, null, null, 63, 29]; // 信任/质量侧（青）

    var opt = baseOption();
    opt.legend = {
      top: 4, left: 0,
      itemWidth: 14, itemHeight: 10,
      textStyle: { color: C.ink, fontFamily: FONT, fontSize: 13 },
      data: [
        { name: '采用率（%）', icon: 'rect' },
        { name: '信任 / 质量（%）', icon: 'rect' }
      ]
    };
    opt.tooltip.axisPointer = { type: 'shadow' };
    opt.tooltip.formatter = function (params) {
      var p = params.filter(function (x) { return x.value != null; })[0];
      if (!p) return '';
      return p.name + '<br/><b>' + p.value + '%</b>';
    };
    opt.xAxis = {
      type: 'value', max: 100,
      axisLabel: { color: C.muted, fontFamily: MONO, fontSize: 11, formatter: '{value}%' },
      axisLine: { show: false },
      splitLine: { lineStyle: { color: C.rule, type: 'dashed' } }
    };
    opt.yAxis = {
      type: 'category',
      inverse: true,
      data: cats,
      axisLabel: { color: C.ink, fontFamily: FONT, fontSize: 13, width: 190, overflow: 'break' },
      axisLine: { lineStyle: { color: C.rule } },
      axisTick: { show: false }
    };
    opt.series = [
      {
        name: '采用率（%）',
        type: 'bar',
        data: adopt,
        barWidth: 18,
        itemStyle: { color: C.accent, borderRadius: [0, 4, 4, 0] },
        label: { show: true, position: 'right', formatter: '{c}%', color: C.accent, fontFamily: MONO, fontSize: 12, fontWeight: 700 },
        z: 3
      },
      {
        name: '信任 / 质量（%）',
        type: 'bar',
        data: trust,
        barWidth: 18,
        itemStyle: { color: C.accent2, borderRadius: [0, 4, 4, 0] },
        label: { show: true, position: 'right', formatter: '{c}%', color: C.accent2, fontFamily: MONO, fontSize: 12, fontWeight: 700 },
        z: 3
      }
    ];
    initChart('chart-trust', opt);
  })();

  /* ---------- 图 3：AI 编程市场规模 ---------- */
  (function () {
    var opt = baseOption();
    opt.tooltip.formatter = function (params) {
      var p = params[0];
      var tag = p.dataIndex === 0 ? '行业估算' : '行业预测';
      return p.name + '<br/>市场规模 <b>$' + p.value + 'B</b><br/><span style="color:' + C.muted + ';font-size:11px;">' + tag + '</span>';
    };
    opt.xAxis = {
      type: 'category',
      data: ['2026', '2032（预测）'],
      axisLabel: { color: C.ink, fontFamily: FONT, fontSize: 13 },
      axisLine: { lineStyle: { color: C.rule } },
      axisTick: { show: false }
    };
    opt.yAxis = {
      type: 'value',
      name: '十亿美元',
      nameTextStyle: { color: C.muted, fontFamily: FONT, fontSize: 11, padding: [0, 0, 0 -24] },
      axisLabel: { color: C.muted, fontFamily: MONO, fontSize: 11, formatter: '${value}B' },
      axisLine: { show: false },
      splitLine: { lineStyle: { color: C.rule, type: 'dashed' } }
    };
    opt.series = [
      {
        name: '市场规模',
        type: 'bar',
        data: [
          { value: 12.8, itemStyle: { color: C.accent, borderRadius: [5, 5, 0, 0] } },
          { value: 30.1, itemStyle: { color: C.accent2Soft, borderColor: C.accent2, borderWidth: 2, borderType: 'dashed', borderRadius: [5, 5, 0, 0] } }
        ],
        barWidth: 92,
        label: {
          show: true, position: 'top',
          formatter: function (p) { return '$' + p.value + 'B'; },
          color: C.ink, fontFamily: MONO, fontSize: 14, fontWeight: 700
        },
        markLine: {
          silent: true,
          symbol: 'none',
          lineStyle: { color: C.muted, type: 'dashed', width: 1.5 },
          label: {
            formatter: '6 年 2.35× · CAGR 约 27%（来源口径）',
            color: C.muted, fontFamily: FONT, fontSize: 11, position: 'middle'
          },
          data: [[{ coord: ['2026', 12.8] }, { coord: ['2032（预测）', 30.1] }]]
        },
        z: 3
      }
    ];
    initChart('chart-market', opt);
  })();

  /* 窗口缩放时重绘所有图表 */
  window.addEventListener('resize', function () {
    charts.forEach(function (c) { try { c.resize(); } catch (_) {} });
  });

  /* ================================================================
   * 3. 目录滚动高亮（scroll-spy）
   * ================================================================ */
  (function () {
    var tocLinks = Array.prototype.slice.call(document.querySelectorAll('.toc a[href^="#"]'));
    if (!tocLinks.length || !('IntersectionObserver' in window)) return;

    var linkById = {};
    tocLinks.forEach(function (a) {
      linkById[a.getAttribute('href').slice(1)] = a;
    });

    var sections = Object.keys(linkById)
      .map(function (id) { return document.getElementById(id); })
      .filter(Boolean);

    var visible = {};
    var observer = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        visible[entry.target.id] = entry.isIntersecting ? entry.intersectionRatio : 0;
      });
      var best = null;
      Object.keys(visible).forEach(function (id) {
        if (visible[id] > 0 && (!best || visible[id] > visible[best])) best = id;
      });
      tocLinks.forEach(function (a) { a.classList.remove('active'); });
      if (best && linkById[best]) linkById[best].classList.add('active');
    }, {
      rootMargin: '-15% 0px -70% 0px',
      threshold: [0, 0.1, 0.25, 0.5]
    });

    sections.forEach(function (s) { observer.observe(s); });
  })();
})();
